import json
import re

def get_commerce_outlays(data, expected_years):
    """Extract Department of Commerce outlays from the JSON data"""
    for elem in data['document']['elements']:
        content = elem.get('content') or ''
        if 'Department of Agriculture (3)' in content and 'Department of Commerce (4)' in content:
            # This is the right table - now find Commerce values
            lines = content.split('<tr>')
            result = {}
            for line in lines:
                # Match fiscal year rows like <td>2016</td>, <td>2017</td>, etc.
                year_match = re.search(r'<td>(20\d{2})</td>', line)
                if year_match:
                    year = year_match.group(1)
                    if year in expected_years or not expected_years:
                        # Get all cells in this row
                        cells = re.findall(r'<td>([^<]*)</td>', line)
                        # Commerce is column 4 (index 3)
                        if len(cells) >= 4:
                            try:
                                commerce_val = int(cells[3].replace(',', ''))
                                result[year] = commerce_val
                            except:
                                pass
            return result
    return None

# Get data from both bulletins
with open('/app/resources/treasury_bulletin_2020_12.json') as f:
    data_2020 = json.load(f)

with open('/app/resources/treasury_bulletin_2024_12.json') as f:
    data_2024 = json.load(f)

# Extract values - 2020 bulletin has 2016-2020
outlays_2020 = get_commerce_outlays(data_2020, ['2016', '2017', '2018', '2019', '2020'])
# 2024 bulletin has 2020-2024
outlays_2024 = get_commerce_outlays(data_2024, ['2020', '2021', '2022', '2023', '2024'])

print("From 2020 bulletin (2016-2020):", outlays_2020)
print("From 2024 bulletin (2020-2024):", outlays_2024)

# Combine to get 2016-2024
all_outlays = {}
if outlays_2020:
    for year, val in outlays_2020.items():
        all_outlays[int(year)] = val
if outlays_2024:
    for year, val in outlays_2024.items():
        all_outlays[int(year)] = val

# Sort by year
all_outlays = dict(sorted(all_outlays.items()))
print("\nAll Department of Commerce total outlays (2016-2024):")
for year, val in all_outlays.items():
    print(f"FY {year}: {val:,}")
EOF
